function smsDetail(d){d=String(d||'');const code=(d.match(/HTTP \d{3}/)||[''])[0],desc=(d.match(/"(?:status_desc|description|message|status)"\s*:\s*"([^"]{1,60})"/i)||[])[1];const rest=d.replace(/\s*·?\s*[\[{].*$/,'').trim();return [code||(!desc?rest:''),desc].filter(Boolean).join(' · ').slice(0,90)||d.slice(0,90);}
