const ACS_AUTO_FORM=`<form id="acs-auto" class="radius-form"><h3>New routers connect themselves (TR-069)</h3><p class="muted">When on, a router that has never been registered can reach the ACS with one shared login. The hub then matches it to a customer by the PPPoE username it reports, or by its WAN address matching a live PPPoE session, registers it and moves it to its own private login. Only clear, single matches are registered; anything else is left for you. Turn the shared login off once your routers are in. Anyone who knows the shared login can connect a device to your ACS while it is on.</p><p id="acs-auto-state" class="muted">Loading…</p><div class="actions"><button type="button" class="button secondary" id="acs-boot">Turn on shared login</button> <button type="button" class="button secondary" id="acs-reg">Turn on automatic registration</button> <button type="button" class="button secondary" id="acs-run">Check now</button></div></form>`;
function wireAcsAuto(){{const f=$('#acs-auto');if(f){const st=$('#acs-auto-state'),b1=$('#acs-boot'),b2=$('#acs-reg'),b3=$('#acs-run');
 const paint=d=>{b1.textContent=d.bootstrap?'Turn off shared login':'Turn on shared login';b2.textContent=d.autoRegister?'Turn off automatic registration':'Turn on automatic registration';
  st.innerHTML=!d.available?'The hub cannot reach the ACS credentials folder yet (it appears after the next deploy).':'Shared login: <b>'+(d.bootstrap?'ON':'off')+'</b> · Automatic registration: <b>'+(d.autoRegister?'ON':'off')+'</b>'+(d.bootstrap?'<br>Username = the router’s serial · Password: <code>'+esc2(d.password)+'</code>'+(d.url?'<br>ACS: '+esc2(d.url):''):'');};
 const esc2=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const call=async body=>{try{paint(await api('cpe/auto','POST',body));}catch(e){toast(e.message);}};
 api('cpe/auto').then(paint).catch(()=>{f.hidden=true;});
 b1.onclick=()=>{const on=!b1.textContent.startsWith('Turn off');if(on&&!confirm('Turn on the shared login? Any device that knows it can connect to your ACS until you turn it off.'))return;call({bootstrap:on});};
 b2.onclick=()=>call({autoRegister:!b2.textContent.startsWith('Turn off')});
 b3.onclick=async()=>{try{const r=await api('cpe/auto/run','POST',{});toast(r.registered.length?'Registered '+r.registered.join(', '):'Nothing new to register'+(r.unmatched.length?' ('+r.unmatched.length+' not matched)':''));}catch(e){toast(e.message);}};}}}
const ksh=n=>'KSh '+Number(n||0).toLocaleString();
const durationText=p=>p.durationValue+' '+(p.durationValue===1?p.durationUnit.replace(/s$/,''):p.durationUnit);
const expiryText=s=>s.expiresAt==null?'No expiry':stamp(s.expiresAt);
const stateBadge=s=>`<span class="status ${s.state==='active'?'online':s.state==='expired'||s.state==='unpaid'?'warning':'offline'}" ${s.deactivatedReason?`title="${h(s.deactivatedReason)}"`:''}>${{active:'Active',expired:'Expired',unpaid:'Never paid',suspended:'Deactivated'}[s.state]||h(s.state)}</span>${s.online&&(s.state==='expired'||s.state==='unpaid')?'<small>online while expired</small>':''}${s.installFeeDue>0?`<small>install fee due KSh ${s.installFeeDue}</small>`:''}`;
const bytesShort=n=>{const u=['B','KB','MB','GB','TB'];let i=0;n=Number(n)||0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return (n>=10||i===0?Math.round(n):n.toFixed(1))+' '+u[i];};
